[[maybe_unused]] size_t WGPUBindingResourceGetExtraRequiredSize([[maybe_unused]] const WGPUBindingResource& record) {
    size_t result = 0;

    const WGPUChainedStruct* next = record.nextInChain;
    while (next != nullptr) {
        switch (next->sType) {
            default: {
                result += WireAlignSizeof<WGPUDawnInjectedInvalidSTypeTransfer>();
                break;
            }
        }
        next = next->next;
    }
    return result;
}
// GetExtraRequiredSize isn't used for structures that are value members of other structures
// because we assume they cannot contain pointers themselves.
DAWN_UNUSED_FUNC(WGPUBindingResourceGetExtraRequiredSize);

[[maybe_unused]] WireResult WGPUBindingResourceSerialize(
    const WGPUBindingResource& record,
    volatile WGPUBindingResourceTransfer* transfer,
    [[maybe_unused]] SerializeBuffer* buffer, const ObjectIdProvider& provider) {

    const WGPUChainedStruct* next = record.nextInChain;
    transfer->hasNextInChain = false;
    while (next != nullptr) {
        transfer->hasNextInChain = true;
        switch (next->sType) {
            default: {
                // Invalid enum. Serialize just the invalid sType for validation purposes.
                dawn::WarningLog() << "Unknown sType " << next->sType << " discarded.";

                volatile WGPUDawnInjectedInvalidSTypeTransfer* chainTransfer;
                WIRE_TRY(buffer->Next(&chainTransfer));
                chainTransfer->chain.sType = WGPUSType_DawnInjectedInvalidSType;
                chainTransfer->chain.hasNext = next->next != nullptr;
                chainTransfer->invalidSType = next->sType;
                break;
            }
        }
        next = next->next;
    }

    WIRE_TRY(provider.GetOptionalId(record.buffer, &transfer->buffer));
    transfer->offset = record.offset;
    transfer->size = record.size;
    WIRE_TRY(provider.GetOptionalId(record.sampler, &transfer->sampler));
    WIRE_TRY(provider.GetOptionalId(record.textureView, &transfer->textureView));

    return WireResult::Success;
}
DAWN_UNUSED_FUNC(WGPUBindingResourceSerialize);

[[maybe_unused]] WireResult WGPUBindingResourceDeserialize(
    WGPUBindingResource* record,
    const volatile WGPUBindingResourceTransfer* transfer,
    DeserializeBuffer* deserializeBuffer,
    [[maybe_unused]] DeserializeAllocator* allocator, const ObjectIdResolver& resolver) {

    WGPUChainedStruct** outChainNext = &record->nextInChain;
    bool hasNext = transfer->hasNextInChain;
    while (hasNext) {
        const volatile WGPUChainedStructTransfer* header;
        WIRE_TRY(deserializeBuffer->Peek(&header));
        WGPUSType sType = header->sType;
        hasNext = header->hasNext;

        switch (sType) {
            case WGPUSType_DawnInjectedInvalidSType: {
                const volatile WGPUDawnInjectedInvalidSTypeTransfer* chainTransfer;
                WIRE_TRY(deserializeBuffer->Read(&chainTransfer));

                WGPUDawnInjectedInvalidSType* typedOutStruct;
                WIRE_TRY(GetSpace(allocator, &typedOutStruct));
                typedOutStruct->chain.sType = sType;
                typedOutStruct->chain.next = nullptr;
                WIRE_TRY(WGPUDawnInjectedInvalidSTypeDeserialize(typedOutStruct, chainTransfer,
                                              deserializeBuffer, allocator, resolver));
                *outChainNext = &typedOutStruct->chain;
                outChainNext = &typedOutStruct->chain.next;
                break;
            }
            default: {
                return WireResult::FatalError;
            }
        }
    }
    *outChainNext = nullptr;

    WIRE_TRY(resolver.GetOptionalFromId(transfer->buffer, &record->buffer));
    static_assert(sizeof(record->offset) >= sizeof(transfer->offset), "Deserialize assignment may not narrow.");
    record->offset = transfer->offset;
    static_assert(sizeof(record->size) >= sizeof(transfer->size), "Deserialize assignment may not narrow.");
    record->size = transfer->size;
    WIRE_TRY(resolver.GetOptionalFromId(transfer->sampler, &record->sampler));
    WIRE_TRY(resolver.GetOptionalFromId(transfer->textureView, &record->textureView));

    return WireResult::Success;
}
DAWN_UNUSED_FUNC(WGPUBindingResourceDeserialize);
